j as (select a.venue_id, a.id, a.year, a.category, a.source_url, lower(substring(a.source_url from '/(?:restaurant|restaurante)/([^/?#]+)')) slug
      from awards a join venues v on v.id=a.venue_id join cities ci on ci.id=v.city_id
      where ci.country_iso='JP' and a.source_id='michelin'),
m as (select l.*, (select count(distinct j.venue_id) from j where j.slug=l.slug) nv,
      (select min(j.venue_id) from j where j.slug=l.slug) vid from l)
select m.g, m.c, m.slug, m.nv, m.vid, v.name, ci.display city, v.status,
 (select string_agg(b.year||':'||b.category||coalesce(':'||b.id,''),', ' order by b.year,b.category) from awards b where b.venue_id=m.vid and b.source_id='michelin') michelin_rows
from m left join venues v on v.id=m.vid left join cities ci on ci.id=v.city_id
order by m.g, m.c, m.slug;